def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = functools.lru_cache(maxsize=maxsize, typed=typed)(func)
        cache_times = {}

        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            current_time = timer()
            if key in cache_times:
                last_time = cache_times[key]
                if current_time - last_time < ttl:
                    return cache(*args, **kwargs)
            result = func(*args, **kwargs)
            cache_times[key] = current_time
            cache.cache_clear()
            cache.cache_info()
            return result

        return wrapper

    return decorator

