def _legacy_mergeOrderings(orderings):
    from collections import deque

    graph = {}
    in_degree = {}
    result = []
    queue = deque()

    for ordering in orderings:
        for i in range(len(ordering)):
            item = ordering[i]
            if item not in graph:
                graph[item] = []
                in_degree[item] = 0
            if i < len(ordering) - 1:
                next_item = ordering[i + 1]
                if next_item not in graph[item]:
                    graph[item].append(next_item)
                    in_degree[next_item] += 1

    for item in graph:
        if in_degree[item] == 0:
            queue.append(item)

    while queue:
        item = queue.popleft()
        result.append(item)

        for neighbor in graph[item]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result

