def difference(d1, d2, level=-1, _level=0):
    if level == 0:
        return {}
    if isinstance(d1, dict) and isinstance(d2, dict):
        result = {}
        keys = set(d1.keys()).union(d2.keys())
        for key in keys:
            if key in d1 and key not in d2:
                result[key] = d1[key]
            elif key in d2 and key not in d1:
                result[key] = d2[key]
            elif isinstance(d1[key],dict) and isinstance(d2[key],dict):
                if level == -1 or _level < level:
                    diff = difference(d1[key], d2[key], level, _level + 1)
                    if diff:
                        result[key] = diff
            elif d1[key] != d2[key]:
                result[key] = d1[key]
        return result
    else:
        return {}

