def _validate_labels(labels: Dict[str, Union[str, List[str]]]) -> None:
    KEY_REGEX = r'^[a-zA-Z0-9 _-]+$'
    VALUE_REGEX = r'^[a-zA-Z0-9 _-]+$'
    errors = []

    for key, value in labels.items():
        if not isinstance(key, str) or not re.match(KEY_REGEX, key):
            errors.append({str(key): "Label key does not match the regex"})
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) or not re.match(VALUE_REGEX, v):
                    errors.append({str(v): "expected string or bytes-like object"})
        elif not isinstance(value, str) or not re.match(VALUE_REGEX, value):
            errors.append({str(value): "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

