    supplement = issue[2:]
    return number, supplement

def absorb(self, args):
    new_args = []
    for arg in args:
        if isinstance(arg, tuple) and len(arg) == 2:
            operator, operands = arg
            if operator == '&':
                if (operand1, operand2) == (operand1, operand1 | operand2):
                    new_args.append(operand1)
                elif (operand1, operand2) == (operand1, ~operand1 & operand2):
                    new_args.append(operand1 & operand2)
            elif operator == '|':
                if (operand1, operand2) == (operand1, operand1 & operand2):
                    new_args.append(operand1)
                elif (operand1, operand2) == (operand1, ~operand1 | operand2):
                    new_args.append(operand1 | operand2)
        else:
            new_args.append(arg)
    return new_args

