from rdflib import Graph, URIRef, Node, Literal

def find_roots(graph: Graph, prop: URIRef, roots: Set[Node] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    parent_to_children = {}
    for s, p, o in graph.triples((None, prop, None)):
        if p not in parent_to_children:
            parent_to_children[p] = set()
        parent_to_children[p].add((s, o))

    nodes_to_visit = set(graph.subjects()) - roots

    while nodes_to_visit:
        current_node = nodes_to_visit.pop()
        for parent, children in parent_to_children.items():
            for child, parent_node in children:
                if current_node == parent_node:
                    nodes_to_visit.add(child)
                    break
            else:
                roots.add(current_node)
                break

    return roots

