from typing import Callable, Tuple, Set

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_block = False
    result = []
    current_tag = []

    for char in text:
        if char == '<':
            if in_block:
                result.append(char)
            else:
                current_tag.append(char)
        elif char == '>':
            if in_block:
                result.append(char)
                if len(current_tag) > 1:
                    tag_word = ''.join(current_tag[1:-1])
                    tags.add(tag_word)
                    if replacer:
                        result.append(replacer(tag_word))
                    else:
                        result.append('<' + tag_word + '>')
                current_tag = []
            else:
                result.append(char)
        elif char == '\n':
            if in_block:
                result.append(char)
            else:
                if current_tag:
                    tag_word = ''.join(current_tag[1:])
                    tags.add(tag_word)
                    if replacer:
                        result.append(replacer(tag_word))
                    else:
                        result.append('<' + tag_word + '>')
                    current_tag = []
                result.append(char)
        elif char == '`' and not in_block:
            if not current_tag:
                in_block = not in_block
            else:
                result.append(char)
        else:
            if in_block:
                result.append(char)
            else:
                current_tag.append(char)

    if current_tag:
        tag_word = ''.join(current_tag[1:])
        tags.add(tag_word)
        if replacer:
            result.append(replacer(tag_word))
        else:
            result.append('<' + tag_word + '>')

    return tags, ''.join(result)

