def _get_conditionally_required_args(self, command_name, options_spec, args):
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            for condition in option['required_when']:
                if condition in args:
                    matched_args.append(option['name'])
                    break
    return list(set(matched_args))

def validate_length_args(self, args, max_length):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :param max_length: The maximum allowed length for the arguments.
    """
    for arg in args:
        if len(arg) > max_length:
            raise ValueError(f"Argument '{arg}' exceeds the maximum length of {max_length}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    available_choices = {'choice1', 'choice2', 'choice3'}  # Define the set of available choices
    for arg in args:
        if arg not in available_choices:
            raise ValueError(f"Invalid choice: {arg}. Available choices are: {available_choices}")

def validate_min_max_args(self, args, min_val, max_val):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :param min_val: The minimum value.
    :param max_val: The maximum value.
    """
    for arg in args:
        if not (min_val <= arg <= max_val):
            raise ValueError(f"Argument {arg} is not between {min_val} and {max_val}")

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control'):
            key, value = arg.split('=')
            control_args[key] = value
        elif arg.startswith('--nested'):
            key, value = arg.split('=')
            nested_args[key] = value
